 "content": "from collections import Counter


def transform(grid):
    """Compare two panels across a solid separator.

    Find the color shared by both panels, fill the result with it, and mark
    coordinates where that color appears on both sides with 3.
    """
    h, w = len(grid), len(grid[0])
    panels = None

    # Find a full-width horizontal separator.
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1:
            panels = (grid[:r], grid[r + 1:])
            break

    # Otherwise find a full-height vertical separator.
    if panels is None:
        for c in range(1, w - 1):
            if all(row[c] == grid[0][c] for row in grid):
                panels = ([row[:c] for row in grid], [row[c + 1:] for row in grid])
                break

    if panels is None:
        raise ValueError("expected a solid panel separator")

    a, b = panels
    if len(a) != len(b) or any(len(ra) != len(rb) for ra, rb in zip(a, b)):
        raise ValueError("panels must have matching dimensions")

    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    # The examples have one shared non-separator color. In ambiguous cases,
    # prefer the most frequent shared color across both panels.
    if not shared:
        raise ValueError("panels have no shared color")
    color = max(shared, key=lambda v: sum(row.count(v) for row in a) + sum(row.count(v) for row in b))

    return [
        [3 if a[r][c] == color and b[r][c] == color else color
         for c in range(len(a[r]))]
        for r in range(len(a))
    ]


if __name__ == "__main__":
    pass
